import{_ as a,o as t,c as o,a0 as r}from"./chunks/framework.CIWPqrYr.js";const n="/manual/assets/03-board.Dr80UWZj.png",u=JSON.parse('{"title":"2. Projects & Boards","description":"","frontmatter":{},"headers":[],"relativePath":"02-projects-and-boards.md","filePath":"02-projects-and-boards.md"}'),s={name:"02-projects-and-boards.md"};function i(l,e,d,c,g,m){return t(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="_2-projects-boards" tabindex="-1">2. Projects &amp; Boards <a class="header-anchor" href="#_2-projects-boards" aria-label="Permalink to &quot;2. Projects &amp; Boards&quot;">​</a></h1><p>Stratos organizes work hierarchically: <strong>Projects</strong> contain <strong>Boards</strong>, and Boards contain your tasks.</p><h2 id="creating-your-first-project" tabindex="-1">Creating Your First Project <a class="header-anchor" href="#creating-your-first-project" aria-label="Permalink to &quot;Creating Your First Project&quot;">​</a></h2><p>A project typically represents a large team or a broad initiative (e.g., &quot;Engineering&quot; or &quot;Q3 Marketing Campaign&quot;).</p><ol><li>In the left sidebar, click the <strong>+</strong> icon next to the <strong>Projects</strong> header.</li><li>Enter a Project Name and an optional description.</li><li>Once created, you will see it listed in your sidebar.</li></ol><h2 id="setting-up-a-board" tabindex="-1">Setting Up a Board <a class="header-anchor" href="#setting-up-a-board" aria-label="Permalink to &quot;Setting Up a Board&quot;">​</a></h2><p>A board represents a specific workflow or product area.</p><p><img src="'+n+'" alt="Board View"></p><ol><li>Hover over your new Project in the sidebar and click the <strong>+</strong> icon to add a Board.</li><li>Give the board a name (e.g., &quot;Frontend Tasks&quot;).</li><li>By default, the board is created with standard Kanban stages: <em>Todo</em>, <em>In Progress</em>, and <em>Done</em>.</li></ol><h3 id="customizing-column-stages" tabindex="-1">Customizing Column Stages <a class="header-anchor" href="#customizing-column-stages" aria-label="Permalink to &quot;Customizing Column Stages&quot;">​</a></h3><p>Every team works differently. To change the workflow:</p><ol><li>Click the <strong>Board Settings</strong> (gear icon) in the top right of the board view.</li><li>Navigate to <strong>Stages</strong>.</li><li>Here you can <strong>Rename</strong>, <strong>Add</strong>, or <strong>Reorder</strong> stages to match your exact process (e.g., adding a &quot;QA Review&quot; column).</li></ol><h2 id="managing-access-inviting-team-members" tabindex="-1">Managing Access &amp; Inviting Team Members <a class="header-anchor" href="#managing-access-inviting-team-members" aria-label="Permalink to &quot;Managing Access &amp; Inviting Team Members&quot;">​</a></h2><p>To collaborate, you need your team!</p><ol><li>In the Board Settings, go to the <strong>Members</strong> tab.</li><li>Type a colleague&#39;s name or email to invite them.</li><li>Assign them a role: <ul><li><strong>Viewer</strong>: Can only read tasks and comment.</li><li><strong>Member</strong>: Can create and edit tasks.</li><li><strong>Admin</strong>: Can modify board settings and stages.</li></ul></li></ol>',15)])])}const h=a(s,[["render",i]]);export{u as __pageData,h as default};
